function parseDuration(str) {
  const match = /^(\d+)(s|m|h|d)$/.exec(str);
  if (!match) {
    return null;
  }
  const digits = match[1];
  const unit = match[2];
  if (!digits || !unit) {
    return null;
  }
  const value = parseInt(digits, 10);
  switch (unit) {
    case "s":
      return value * 1e3;
    case "m":
      return value * 6e4;
    case "h":
      return value * 36e5;
    case "d":
      return value * 864e5;
    default:
      return null;
  }
}
function formatDuration(ms) {
  const days = Math.floor(ms / 864e5);
  const hours = Math.floor(ms % 864e5 / 36e5);
  const minutes = Math.floor(ms % 36e5 / 6e4);
  const parts = [];
  if (days > 0) {
    parts.push(`${days}d`);
  }
  if (hours > 0) {
    parts.push(`${hours}h`);
  }
  if (minutes > 0) {
    parts.push(`${minutes}m`);
  }
  if (parts.length === 0) {
    parts.push(`${Math.ceil(ms / 1e3)}s`);
  }
  return parts.join(" ");
}

